import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  const [history, setHistory] = useState(
    JSON.parse(localStorage.getItem("history")) || []
  );

  const [showProfile, setShowProfile] = useState(false);
  const [user, setUser] = useState(
    JSON.parse(localStorage.getItem("user")) || {
      name: "User",
      email: "user@email.com"
    }
  );

  useEffect(() => {
    localStorage.setItem("history", JSON.stringify(history));
    localStorage.setItem("user", JSON.stringify(user));
  }, [history, user]);

  // ✅ DETECT SOURCE
  const detectSource = (txns, fallback) => {
    if (fallback && fallback !== "unknown") return fallback;

    const text = JSON.stringify(txns).toLowerCase();

    if (text.includes("gpay") || text.includes("google pay")) return "GPay";
    if (text.includes("paytm")) return "Paytm";
    if (text.includes("phonepe")) return "PhonePe";

    return "Bank Statement";
  };

  // ✅ UPLOAD
  const handleUpload = async () => {
    if (!file) return alert("Please select a PDF file");

    setLoading(true);

    try {
      const formData = new FormData();
      formData.append("file", file);

      const res = await fetch("http://localhost:8000/upload-statement/", {
        method: "POST",
        body: formData
      });

      const data = await res.json();

      const txns = data.transactions || [];
      const detectedType = detectSource(txns, data.detected_type);

      setTransactions(txns);
      setType(detectedType);

      const newEntry = {
        id: Date.now(),
        date: new Date().toLocaleString(),
        type: detectedType,
        count: txns.length,
        transactions: txns
      };

      setHistory((prev) => [newEntry, ...prev]);

      setActiveTab("transactions");
    } catch (err) {
      alert("Upload failed");
    }

    setLoading(false);
  };

  // ✅ DELETE HISTORY
  const deleteHistory = (id) => {
    const updated = history.filter((item) => item.id !== id);
    setHistory(updated);
  };

  // ✅ VIEW HISTORY
  const viewHistory = (item) => {
    setTransactions(item.transactions || []);
    setType(item.type);
    setActiveTab("transactions");
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div className="logo">FinSight</div>

          <div className="nav-actions">

            {/* TABS */}
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "transactions" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("transactions")}
              >
                Transactions
              </span>
            </div>

            {/* PROFILE ICON */}
            <div
              className="theme-circle"
              onClick={() => setShowProfile(true)}
              title="Profile"
            >
              👤
            </div>

            {/* DARK MODE */}
            <div
              className={`theme-circle ${darkMode ? "dark" : "light"}`}
              onClick={() => setDarkMode(!darkMode)}
            ></div>
          </div>
        </div>

        {/* HERO */}
        <div className="hero">
          <h1>Welcome, {user.name}</h1>
          <p>Your financial overview</p>
        </div>

        {/* KPI */}
        <div className="kpi-grid">
          <div className="kpi-card">
            <h4>Statement Source</h4>
            <p>{type || "Not uploaded"}</p>
          </div>

          <div className="kpi-card">
            <h4>Total Transactions</h4>
            <p>{transactions?.length || 0}</p>
          </div>

          <div className="kpi-card">
            <h4>Status</h4>
            <p>{transactions?.length ? "Processed" : "Waiting"}</p>
          </div>
        </div>

        {/* OVERVIEW */}
        {activeTab === "overview" && (
          <div className="top-section">
            <div className="card upload-card">
              <h3>Upload Statement</h3>

              <div className="upload-row">
                <input
                  type="file"
                  accept=".pdf"
                  onChange={(e) => setFile(e.target.files[0])}
                />

                <button onClick={handleUpload}>
                  {loading ? "Processing..." : "Analyze Statement"}
                </button>
              </div>
            </div>

            <div className="card summary-card">
              <h3>Insights Summary</h3>
              <p>AI-powered transaction analysis with categorization</p>
            </div>
          </div>
        )}

        {/* TRANSACTIONS + HISTORY */}
        {activeTab === "transactions" && (
          <>
            {/* TABLE */}
            {transactions.length > 0 && (
              <div className="card table-card">
                <h3>Transaction Ledger</h3>

                <div className="table-wrapper">
                  <table>
                    <thead>
                      <tr>
                        <th>Date</th>
                        <th>Type</th>
                        <th>Description</th>
                        <th>Amount</th>
                        <th>Category</th>
                        <th>Need/Want</th>
                      </tr>
                    </thead>

                    <tbody>
                      {transactions.map((txn, i) => (
                        <tr key={i}>
                          <td>{txn.date}</td>
                          <td className={txn.type === "debit" ? "debit" : "credit"}>
                            {txn.type}
                          </td>
                          <td>{txn.description}</td>
                          <td>₹{txn.amount}</td>
                          <td>{txn.category || "-"}</td>
                          <td>{txn.need_or_want || "-"}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* HISTORY */}
            <div className="card table-card">
              <h3>Upload History</h3>

              <div className="table-wrapper">
                <table>
                  <thead>
                    <tr>
                      <th>Date</th>
                      <th>Source</th>
                      <th>Transactions</th>
                      <th>Action</th>
                    </tr>
                  </thead>

                  <tbody>
                    {history.map((h) => (
                      <tr key={h.id}>
                        <td>{h.date}</td>
                        <td>{h.type}</td>
                        <td>{h.count}</td>
                        <td>
                          <button onClick={() => viewHistory(h)}>View</button>
                          <button onClick={() => deleteHistory(h.id)}>Delete</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </>
        )}

        {/* PROFILE MODAL */}
        {showProfile && (
          <div className="profile-modal">
            <div className="profile-card">
              <h3>User Profile</h3>

              <input
                type="text"
                value={user.name}
                onChange={(e) =>
                  setUser({ ...user, name: e.target.value })
                }
              />

              <input
                type="email"
                value={user.email}
                onChange={(e) =>
                  setUser({ ...user, email: e.target.value })
                }
              />

              <div style={{ marginTop: "10px" }}>
                <button onClick={() => setShowProfile(false)}>Save</button>
                <button onClick={() => setShowProfile(false)}>Close</button>
              </div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
